import * as React from "react"
import { mergeProps } from "@base-ui/react/merge-props"
import { useRender } from "@base-ui/react/use-render"
import { cva, type VariantProps } from "class-variance-authority"

import { cn } from "@/lib/utils"

/* The ALL-CAPS section label (skin-spec §0.5 / §19) as a component, in two registers.
 *
 * `mono` is the default and the one the name comes from: the `eyebrow` utility — mono, 500,
 * uppercase, `text-faint`. `md` is that utility verbatim; the other sizes are the kits'
 * smaller and larger caps recipes normalised onto one scale.
 *
 * `nav` is the sidebar group label. Measured on the Luminars shell 2026-08-24: at the mono
 * recipe a group label reads as heavy as the nav rows it is supposed to label, so this
 * register drops to the text face at 10px/400 with looser tracking. It replaces the mono
 * recipe rather than layering over it, so `size` applies to `mono` only. */
const eyebrowVariants = cva("inline-flex items-baseline", {
  variants: {
    register: {
      mono: "eyebrow",
      nav: "font-sans text-[10px] leading-[1.3] font-normal tracking-[0.06em] text-faint uppercase",
    },
    size: {
      xs: "text-[9.5px] tracking-[0.08em]",
      sm: "text-[10px] tracking-[0.08em]",
      md: "",
      lg: "text-xs tracking-[0.14em]",
    },
    tint: {
      none: "",
      demand: "text-unit-demand",
      piattaforma: "text-unit-piattaforma",
      academy: "text-unit-academy",
      installatori: "text-unit-installatori",
    },
  },
  defaultVariants: {
    register: "mono",
    size: "md",
    tint: "none",
  },
})

type EyebrowProps = useRender.ComponentProps<"span"> &
  VariantProps<typeof eyebrowVariants> & {
    /** The numbered-index form ("01"…"06"): rendered in the warm accent before the label. */
    index?: string | undefined
  }

function Eyebrow({
  className,
  register = "mono",
  size = "md",
  tint = "none",
  index,
  render,
  children,
  ...props
}: EyebrowProps) {
  return useRender({
    defaultTagName: "span",
    props: mergeProps<"span">(
      {
        className: cn(
          eyebrowVariants({ register, size: register === "nav" ? "md" : size, tint }),
          className
        ),
        children: (
          <>
            {index ? (
              <b
                data-slot="eyebrow-index"
                className="mr-[0.625em] font-medium text-ochre"
              >
                {index}
              </b>
            ) : null}
            {children}
          </>
        ),
      },
      props
    ),
    render,
    state: {
      slot: "eyebrow",
      register,
      size,
    },
  })
}

/* The marketing section header (skin-spec §19): numbered eyebrow + h2 + optional lead, with the
 * measure rules. The title takes the `h2` utility — the display face on purpose (this is a band,
 * not the product surface, so it does not ask the brand which voice to use) at the SURFACE's
 * size, so the same header reads at field scale on paper and at product scale in an app. */
function SectionHead({
  className,
  index,
  eyebrow,
  title,
  lead,
  serifLead = false,
  align = "start",
  ...props
}: Omit<React.ComponentProps<"div">, "title"> & {
  index?: string | undefined
  eyebrow: React.ReactNode
  title: React.ReactNode
  lead?: React.ReactNode
  /** Switches the lead to the serif editorial voice. */
  serifLead?: boolean
  align?: "start" | "center"
}) {
  return (
    <div
      data-slot="section-head"
      data-align={align}
      /* A section head fades in with the band it introduces — the observer reads the attribute. */
      data-reveal=""
      className={cn(
        "mb-[clamp(2.5rem,4vw,3.5rem)] max-w-[max(38rem,70%)]",
        align === "center" && "mx-auto max-w-[56ch] text-center",
        className
      )}
      {...props}
    >
      <Eyebrow size="lg" index={index} className="mb-5 block">
        {eyebrow}
      </Eyebrow>
      <h2
        data-slot="section-head-title"
        className="h2"
      >
        {title}
      </h2>
      {lead !== undefined && lead !== null ? (
        <p
          data-slot="section-head-lead"
          className={cn(
            "mt-4 max-w-[max(32rem,62%)] text-muted-foreground",
            align === "center" && "mx-auto max-w-[48ch]",
            serifLead && "font-serif"
          )}
        >
          {lead}
        </p>
      ) : null}
    </div>
  )
}

/** The four Revenue Farm business units — the only place a tint is allowed to name a thing. */
type UnitTint = "demand" | "piattaforma" | "academy" | "installatori"

export { Eyebrow, SectionHead, eyebrowVariants }
export type { UnitTint }
